/**
 * gh-1380: the crossing's pre-classifier stamp action for a matched
 * signature, or null (unrecognized → the analyzer leg handles it).
 */
function transientCrossingAction(faState, faCfg, backoff) {
    var stamp = failureAnalyzerModule.transientPreClassifierVerdict(
        faState.streakSignature, faCfg.transientPatterns, faState.streakCount, backoff);
    if (!stamp) return null;
    return {
        type: 'transientVerdict',
        verdict: stamp,
        reason: 'known-transient failure signature — pre-classified transient without AI' +
            (faState.streakSignature ? ' (signature: ' + faState.streakSignature + ')' : '')
    };
}

/**
 * gh-1380 rework (review fail-safe): the crossing stamp is trusted back
 * ONLY through the machine-identity allowlist (the gh-807 fail-closed
 * parse — without `machineAuthor` configured, machineLogins is empty and
 * NOTHING parses as trusted). An absorbed dispatch could then never
 * resume: the crossing would re-fire every tick and the loop would wedge
 * with zero retries. So the window (and the dispatch absorption) is
 * armed only when the stamp can be trusted back; otherwise the crossing
 * degrades to the backoff = 1 shape — the stamp still lands before the
 * riding dispatch (classification + audit trail stay honest) and the
 * retries ALWAYS continue (the gh-1366 wasteful-but-live degrade).
 */
function stampBackoffOf(cfg, backoff) {
    return (backoff > 1 && machineLoginsOf(cfg).length > 0) ? backoff : 1;
}


/**
 * The gh-1366 analyzer divert action — the crossing's dispatch becomes
 * the analyze leg (the reason string is verbatim gh-1366).
 */
function analyzerDivertAction(afterFailures, signature) {
    return {
        type: 'dispatch',
        leg: failureAnalyzerModule.ANALYZE_LEG,
        reason: 'failure streak of ' + afterFailures + ' identical failures — the analyzer leg ' +
            'classifies transient vs deterministic before more blind retries' +
            (signature ? ' (signature: ' + signature + ')' : '')
    };
}

/**
 * Splice ONE replacement in place of the dispatch at `index` — replacing
 * it (divert / absorb) or riding it through after an inserted stamp.
 */
function spliceDispatchAction(actions, index, replacement, replaceDispatch) {
    var tail = replaceDispatch ? index + 1 : index;
    return actions.slice(0, index).concat([replacement]).concat(actions.slice(tail));
}

/**
 * The blind-retry gate (gh-1366 AC1): a re-dispatch decision crossing the
 * afterFailures threshold is diverted to the analyzer leg ONCE — exactly
 * the crossing, so a crashed analyzer (no verdict → nothing consumed)
 * moves the streak past the threshold and blind retries continue (AC5).
 * Only dispatch actions divert; escalations (needs-human labels) ride on.
 *
 * gh-1380: the deterministic transient pre-classifier runs FIRST at the
 * crossing — pure logic, zero AI. A signature matching any configured
 * `transientPatterns` regex is classified BY THE SM ITSELF: the verdict
 * stamp lands (the audit trail + the consumption discount that resets the
 * effective counter, gh-1366 transient semantics) and the retry dispatch
 * rides through — or, with backoff > 1, waits out the window (the
 * classification tick IS backoff tick 1; see gateTransientBackoff).
 * Unrecognized signatures divert to the analyzer leg exactly as today —
 * unless analyzerEnabled is false (no AI anywhere: plain blind retry).
 */
function gateBlindRedispatch(actions, state, cfg) {
    if (!failureAnalysisEnabledOf(cfg)) return actions;
    var faState = failureAnalysisStateOf(state);
    if (!faState) return actions;
    var faCfg = cfg.failureAnalysis;
    var consumed = failureAnalyzerModule.consumedCount(faState.verdicts, faState.streakSignature);
    if (!failureAnalyzerModule.analysisDue(faState.streakCount, consumed, faCfg.afterFailures)) {
        return actions;
    }
    var firstDispatch = firstDispatchIndex(actions);
    if (firstDispatch === -1) return actions;
    var backoff = stampBackoffOf(cfg, faCfg.backoff);
    var stampAction = transientCrossingAction(faState, faCfg, backoff);
    if (stampAction) {
        return spliceDispatchAction(actions, firstDispatch, stampAction, backoff > 1);
    }
    }
    if (faCfg.analyzerEnabled === false) return actions;
    return spliceDispatchAction(actions, firstDispatch,
        analyzerDivertAction(faCfg.afterFailures, faState.streakSignature), true);
}

