// gh-1380 rework (review NIT): the compiled-form memo. Config entries are
// validated compilable at SM start, but `transientPatternMatches` may be
// called per pattern per evaluation — recompiling each time is waste; a
// source→RegExp memo serves the compiled form. A failed compile memoizes
// null (the fail-safe: no-match, retried compile is harmless and rare —
// only hand-built configs can carry uncompilable entries).
var TRANSIENT_PATTERN_CACHE = {};

function compiledTransientPattern(source) {
   if (typeof source !== 'string' || !source) return null;
   if (TRANSIENT_PATTERN_CACHE[source] === undefined) {
       var re = null;
       try { re = new RegExp(source, 'i'); } catch (eRegex) { re = null; }
       TRANSIENT_PATTERN_CACHE[source] = re;
   }
   return TRANSIENT_PATTERN_CACHE[source];
}

function transientPatternMatches(source, text) {
   var re = compiledTransientPattern(source);
   return !!re && re.test(text);
}
``

